  render: () => stage(<p style={{
    margin: 0
  }}>
        Read our{' '}
        <HoverCard trigger={<a href="#guide" style={link}>
              guide to Lisbon's best cafés
            </a>} width="320px">
          <AspectRatio ratio="16:9" rounded>
            <img src={aspectRatioPhoto} alt="" />
          </AspectRatio>
          <div style={{
        display: 'grid',
        gap: 4
      }}>
            <span style={{
          fontWeight: 500
        }}>12 cafés worth the trip in Lisbon</span>
            <span style={muted}>From tiny espresso bars to garden terraces, where to sit down for a bica.</span>
          </div>
          <span style={{
        ...muted,
        fontSize: 12,
        lineHeight: '16px'
      }}>citylife.com · 6 min read</span>
        </HoverCard>
        .
      </p>)
